/* * @lc app=leetcode id=1300 lang=kotlin * * [1300] Sum of Mutated Array Closest to Target */ class Solution { fun findBestValue(arr: IntArray, target: Int): Int = (0..(arr.maxOrNull() ?: 0)).run { fold(0 to maxOrNull()!!) { (l, r), _ -> if (l < r) ((l + r) / 2).let { m -> if (arr.sumOf { minOf(it, m) } >= target) l to m else m + 1 to r } else l to r }.first }.let { ans -> if (Math.abs(arr.sumOf { minOf(it, ans - 1) } - target) <= Math.abs(arr.sumOf { minOf(it, ans) } - target)) ans - 1 else ans } }